const stats = flow.get("stats") || { valid: 0, invalid: 0, reasons: {}, last_seen: {} };

function reject(reason) {
    stats.invalid++;
    stats.reasons[reason] = (stats.reasons[reason] || 0) + 1;
    flow.set("stats", stats);
    node.status({ fill: "red", shape: "dot", text: "last reject: " + reason });
    return [null, {
        topic: "deadletter/" + reason,
        payload: { reason: reason, original_topic: msg.topic, raw: String(msg.payload).slice(0, 500) }
    }];
}

// 1. topic shape: tenant/<t>/depot/<d>/sensor/<s>
const p = msg.topic.split("/");
if (p.length !== 6 || p[0] !== "tenant" || p[2] !== "depot" || p[4] !== "sensor") {
    return reject("bad_topic");
}

// 2. JSON
let d;
try { d = JSON.parse(String(msg.payload)); } catch (e) { return reject("bad_json"); }
if (d === null || typeof d !== "object" || Array.isArray(d)) { return reject("bad_json"); }

// 3. required fields
for (const k of ["tenant_id", "depot_id", "device_id"]) {
    if (typeof d[k] !== "string" || d[k] === "") { return reject("missing_" + k); }
}

// 4. topic and payload must agree (cross-company safety check)
if (p[1] !== d.tenant_id || p[3] !== d.depot_id || p[5] !== d.device_id) {
    return reject("topic_payload_mismatch");
}

// 5. values
const num = (v) => typeof v === "number" && Number.isFinite(v);
if (d.status === "PROBE_ERROR") {
    // the firmware reports a dead probe on purpose, so no numbers are required
} else {
    if (!num(d.temperature_celsius)) { return reject("missing_temperature"); }
    if (d.temperature_celsius < -60 || d.temperature_celsius > 80) { return reject("temperature_out_of_range"); }
}
if (d.probe_temperature_celsius !== undefined && d.probe_temperature_celsius !== null) {
    const t = d.probe_temperature_celsius;
    if (!num(t) || t < -55 || t > 125 || t === 85 || t === -127) { return reject("probe_glitch"); }
}
if (d.humidity_percent !== undefined && d.humidity_percent !== null) {
    if (!num(d.humidity_percent) || d.humidity_percent < 0 || d.humidity_percent > 100) { return reject("humidity_out_of_range"); }
}

stats.valid++;
stats.last_seen[d.tenant_id + "/" + d.depot_id] = new Date().toISOString();
flow.set("stats", stats);
node.status({ fill: "green", shape: "dot", text: "valid: " + stats.valid + "  rejected: " + stats.invalid });
return [{ topic: "clean/" + msg.topic, payload: msg.payload }, null];

msg.payload = flow.get("stats") || { valid: 0, invalid: 0, reasons: {}, last_seen: {} };
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
return msg;
